strings:
body { font: 16px/1.4 sans-serif; margin: 0 8px; color: #111; }
header { display: flex; gap: 16px; align-items: baseline; border-bottom: 1px solid #ccc; }
header nav a { margin-right: 12px; }
.lead img, .lead video { display: block; width: 480px; height: 270px; object-fit: cover; }
.live { color: #c00; font-weight: bold; }
.stories { display: grid; grid-template-columns: repeat(auto-fill, minmax(240px, 1fr)); gap: 16px; }
.stories img { display: block; width: 240px; height: 135px; object-fit: cover; }
.meta { color: #666; font-size: 14px; }
figure { margin: 8px 0; }
